<?php require 'includes/functions.php';$d=query('SELECT d.*,u.name donor_name,u.phone donor_phone FROM donations d JOIN users u ON u.id=d.donor_id WHERE d.id=?',[(int)($_GET['id']??0)])->fetch();if(!$d){http_response_code(404);exit('Donation not found.');}$u=user();$involved=$u&&($u['role']==='admin'||$u['id']==$d['donor_id']||$u['id']==$d['orphanage_id']);$title=$d['title'];require 'includes/header.php';?><section class="section"><a class="text-link" href="<?=url('donations.php')?>">← Back to donations</a><div class="detail-grid"><div><img class="detail-image" src="<?=url(food_image($d['category']))?>" alt="<?=e($d['category'])?> illustration"><div class="panel"><h3>About this donation</h3><p><?=nl2br(e($d['description']))?></p><p><b>Allergen information:</b> <?=e($d['allergens'])?></p><small>Please confirm food condition and dietary suitability directly with the donor before collection.</small></div></div><div><?=badge($d['status'])?><h1><?=e($d['title'])?></h1><p>Shared by <?=e($d['donor_name'])?></p><div class="facts"><div><small>QUANTITY</small><strong><?=(int)$d['quantity']?> servings</strong></div><div><small>FOOD TYPE</small><strong><?=e($d['food_type'])?></strong></div><div><small>CITY</small><strong><?=e($d['city'])?></strong></div><div><small>COLLECT BEFORE</small><strong><?=e(date('d M Y, h:i A',strtotime($d['deadline'])))?></strong></div></div>
<?php if($involved):?><div class="panel"><h3>Pickup information</h3><p><?=nl2br(e($d['address']))?></p><p>Donor phone: <?=e($d['donor_phone'])?></p><?php if($d['orphanage_id']):$receiver=query('SELECT name,phone FROM users WHERE id=?',[$d['orphanage_id']])->fetch();?><p>Receiving orphanage: <?=e($receiver['name'])?><br>Phone: <?=e($receiver['phone'])?></p><?php endif;?><p>Pickup arrangement: <?=e($d['pickup_note']?:'Not arranged yet')?></p></div><?php endif;?>
<?php if($u&&$u['role']==='orphanage'&&$u['status']==='approved'&&$d['status']==='pending'):?><form class="panel" action="<?=url('actions/donation-actions.php')?>" method="post"><?=csrf()?><input type="hidden" name="action" value="accept"><input type="hidden" name="id" value="<?=$d['id']?>"><label>Pickup plan / transport contact<textarea name="pickup_note" required maxlength="500" placeholder="Who will collect the food, and when?"></textarea></label><button class="button full" data-confirm="Accept this donation and arrange pickup before the deadline?">Accept donation <?=icon('arrow')?></button></form><?php elseif(!$u && $d['status']==='pending'):?><a class="button" href="<?=url('login.php')?>">Log in as an orphanage to accept</a><?php endif;?>
<?php if($u&&$u['id']==$d['orphanage_id']&&$d['status']==='accepted'):?><form class="panel" action="<?=url('actions/donation-actions.php')?>" method="post"><?=csrf()?><input type="hidden" name="id" value="<?=$d['id']?>"><label>Pickup arrangement<textarea name="pickup_note" maxlength="500" required><?=e($d['pickup_note'])?></textarea></label><button class="button outline" name="action" value="pickup">Update pickup</button><button class="button" name="action" value="collect" data-confirm="Confirm the food has been received?">Mark collected</button><button class="plain" name="action" value="release" data-confirm="Release this donation for another orphanage?">Cancel acceptance</button></form><?php endif;?>
<?php if($u&&$u['id']==$d['donor_id']&&$d['status']==='pending'):?><a class="button" href="<?=url('donor/edit-donation.php?id='.$d['id'])?>">Edit donation</a><form class="inline" action="<?=url('actions/donation-actions.php')?>" method="post"><?=csrf()?><input type="hidden" name="id" value="<?=$d['id']?>"><button class="button outline" name="action" value="cancel" data-confirm="Cancel this donation?">Cancel donation</button></form><?php endif;?>
<?php if($involved):?><h3>Donation timeline</h3><ul class="timeline"><?php foreach(query('SELECT * FROM donation_events WHERE donation_id=? ORDER BY id',[$d['id']])->fetchAll() as $ev):?><li><b><?=e($ev['message'])?></b><small><?=e($ev['created_at'])?></small></li><?php endforeach;?></ul><?php endif;?></div></div></section><?php require 'includes/footer.php';?>